```python
def _get_cythonized_result(
    self,
    how,
    grouper,
    aggregate=False,
    cython_dtype=None,
    needs_values=False,
    needs_mask=False,
    needs_ngroups=False,
    result_is_index=False,
    pre_processing=None,
    post_processing=None,
    **kwargs
):
    if result_is_index and aggregate:
        raise ValueError("'result_is_index' and 'aggregate' cannot both be True!")
    if post_processing and not callable(post_processing):
        raise ValueError("'post_processing' must be a callable!")
    if pre_processing and not callable(pre_processing):
        raise ValueError("'pre_processing' must be a callable!")
    if pre_processing and not needs_values:
        raise ValueError(
            "Cannot use 'pre_processing' without specifying 'needs_values'!"
        )

    labels, _, ngroups = grouper.group_info
    output = collections.OrderedDict()
    base_func = getattr(libgroupby, how)

    for name, obj in self._iterate_slices():
        if aggregate:
            result_sz = ngroups
        else:
            result_sz = len(obj)

        if not cython_dtype:
            cython_dtype = obj.dtype

        result = np.empty(result_sz, dtype=cython_dtype)
        func = partial(base_func, result, labels)
        inferences = None

        if needs_values:
            vals = obj.values
            if pre_processing:
                vals, inferences = pre_processing(vals)
            func = partial(func, vals)

        if needs_mask:
            mask = isna(obj.values).view(np.uint8)
            func = partial(func, mask)

        if needs_ngroups:
            func = partial(func, ngroups)

        func(**kwargs)  # Call func to modify indexer values in place

        if result_is_index:
            result = algorithms.take_nd(obj.values, result)

        if post_processing:
            result = post_processing(result, inferences)

        output[name] = result.astype(obj.dtype)

    if aggregate:
        return self._wrap_aggregated_output(output)
    else:
        return self._wrap_transformed_output(output)
